#!/bin/sh
cd "$(dirname "$0")"
./gen_items.sh items_food "4 x 4 grid, square 1024 x 1024. Left to right, top to bottom: apple (shiny red apple with a leaf), bread (a golden-brown loaf), raw beef (a red steak with white fat edge), cooked beef (a browned steak with grill marks), raw chicken (a pale pink drumstick and thigh), cooked chicken (a golden roasted drumstick), raw mutton (a red lamb chop with a bone), cooked mutton (a browned lamb chop with a bone), raw porkchop (a pink pork chop), cooked porkchop (a browned pork chop), rotten flesh (a greenish grey ragged piece of meat), spider eye (a glossy dark red eye), egg (a smooth pale cream egg), wheat (a bundle of golden wheat stalks), wheat seeds (a small pile of green-gold seeds), sugar (a small heap of white sugar)." &
./gen_items.sh items_armor "4 x 4 grid, square 1024 x 1024, one row per material, left to right in each row: helmet, chestplate, leggings, boots, all seen from the front-left and empty inside. Row 1 leather (warm brown matte leather with stitching), row 2 iron (pale cool silver with a blue tint, smooth, one bright edge highlight), row 3 gold (saturated yellow-gold, shiny, small white glints), row 4 diamond (cyan crystal plates with sharp facets and white sparkles)." &
wait
./gen_items.sh items_misc "4 x 4 grid, square 1024 x 1024. Left to right, top to bottom: bucket (an empty iron bucket with a handle), water bucket (the iron bucket full of blue water), lava bucket (the iron bucket full of glowing orange lava), string (a small coil of white string), bandage (a rolled cream cloth bandage), torch (a wooden stick with a bright flame on top), redstone torch (a wooden stick with a glowing red tip), lever (a small wooden lever on a cobblestone base), repeater (a stone slab with two small red torches on it), comparator (a stone slab with three small red torches in a triangle), kibble (a small sack of brown pet food pellets), nest (a round woven twig nest), raptor egg (a large speckled tan egg), sedative (a small glass vial of violet liquid), utahraptor saddle (a sturdy brown leather saddle with straps), wyvern saddle (a dark leather saddle with bronze fittings and wing straps)." &
./gen_items.sh items_eggs "2 x 4 grid (two rows of four), landscape 1536 x 1024. Each is a spawn egg (an egg shape with a base colour and spots of a second colour), left to right, top to bottom: chicken (white with red spots), cow (dark brown with light grey spots), creeper (green with black spots), pig (pink with darker pink spots), sheep (white with pale pink spots), skeleton (light grey with dark grey spots), spider (dark brown-black with red spots), zombie (teal blue with green spots)." &
wait
